CREATE CACHED TABLE "PUBLIC"."EVENTS"(
    "ID" INTEGER GENERATED BY DEFAULT AS IDENTITY(START WITH 1 RESTART WITH 7) NOT NULL,
    "TITLE" CHARACTER VARYING(255) NOT NULL,
    "TYPE" CHARACTER VARYING(100) NOT NULL,
    "LOCATION" CHARACTER VARYING(255) NOT NULL,
    "PRICE" DOUBLE PRECISION NOT NULL,
    "SIZE" CHARACTER VARYING(50) NOT NULL,
    "DESCRIPTION" CHARACTER VARYING(2000),
    "IMAGE_LOCATION" CHARACTER VARYING(500),
    "OWNER_ID" INTEGER,
    "LATITUDE" DOUBLE,
    "LONGITUDE" DOUBLE
);   
ALTER TABLE "PUBLIC"."EVENTS" ADD CONSTRAINT "PUBLIC"."CONSTRAINT_7" PRIMARY KEY("ID");        
